  ('lawful-presence-visa-i94', 'Valid visa with passport and I-94 (and EAD if applicable)', '', 'bring_in', '{}'),
  ('social-security-card', 'Original Social Security card — or an accepted SSN alternative (see notes)', 'The original card is preferred, but if you don''t have it the office routinely accepts an alternative that shows your SSN: a W-2, any 1099 form, Form 1095-C, a pay stub, or the office''s self-certification of Social Security number. (Source: tcslc-sme policy-questions DL-1, 2026-07.)', 'bring_in', '{}'),
  ('address-proof-1', 'Proof of St. Lucie County residential address #1 (deed, mortgage statement, lease, current utility bill, voter registration card, bank statement, or official mail dated within 60 days)', 'FLHSMV requires TWO proofs of Florida residential address, each from a different source. Must show residency of more than 30 days and be dated within 60 days.', 'optional_upload', '{}'),
  ('address-proof-2', 'Proof of St. Lucie County residential address #2 (from a different source than #1)', 'FLHSMV requires two documents from different sources.', 'optional_upload', '{}'),
  ('declaration-of-domicile', 'Declaration of Domicile from the St. Lucie County Clerk of the Circuit Court — substitutes for one of the required proofs of FL address', 'FLHSMV requires TWO proofs of Florida residential address (from different sources). This Declaration of Domicile substitutes for a proof you''re missing. Get it from the Clerk of Court''s Recording Department: fill it out, get it notarized, then record it at the Clerk''s office before your tax collector visit.', 'form', '{}'),
  ('name-change-marriage-cert', 'Certified marriage certificate (for name change; church-issued not accepted)', '', 'bring_in', '{}'),
  ('name-change-divorce-decree', 'Certified divorce decree (for name change)', '', 'bring_in', '{}'),
  ('name-change-court-order', 'Certified court order of name change', '', 'bring_in', '{}'),
  ('oos-license', 'Current out-of-state driver license', '', 'bring_in', '{}'),
  ('certified-driving-record', 'Certified driving record from prior state (required when license cannot be verified in NLETS)', '', 'bring_in', '{}'),
  ('vision-test-or-dl10', 'Corrective lenses (if needed) OR completed HSMV 72010 Report of Eye Examination', '', 'bring_in', '{}'),
  ('military-orders', 'Copy of military orders (active-duty service members)', '', 'optional_upload', '{}'),
  ('hsmv-82040', 'Application for Certificate of Title (HSMV 82040)', '', 'form', '{}'),
  ('hsmv-82042', 'VIN and Odometer Verification (HSMV 82042)', 'Required for out-of-state vehicles. Must be completed by FL DMV compliance examiner, FL licensed dealer, FL notary, law enforcement officer, or US Military Police. Not required if vehicle is brought to the office parking lot for on-site VIN verification.', 'form', '{}'),
  ('hsmv-82053', 'Power of Attorney for a Motor Vehicle, Mobile Home, Vessel, or Vessel with Trailer (HSMV 82053)', '', 'form', '{}'),
  ('hsmv-82050', 'Notice of Sale / Bill of Sale (HSMV 82050)', 'Required when purchaser name is missing from the title assignment or when odometer disclosure needs a separate document.', 'form', '{}'),
  ('original-vehicle-title', 'Original vehicle title, signed by all registered owners (photocopies not accepted)', '', 'bring_in', '{}'),
  ('oos-registration', 'Current out-of-state registration (dated within the last 6 months)', '', 'optional_upload', '{}'),
  ('bill-of-sale-purchase-agreement', 'Bill of sale or purchase agreement', 'Used to prove sales tax paid out of state (if owned less than 6 months) and/or to supply odometer disclosure when the title is missing it.', 'optional_upload', '{}'),
  ('proof-oos-sales-tax', 'Proof of sales tax paid in previous state (bill of sale, dealer invoice, or tax receipt)', 'Applies only when vehicle owned less than 6 months. Without proof, FL collects full 6% Use Tax + local option tax.', 'optional_upload', '{}'),
  ('lien-letter', 'Lienholder letter on letterhead with VIN, make, and year (or copy of OOS title showing the lien)', '', 'optional_upload', '{}'),
  ('lease-agreement-with-lessor-letter', 'Lease agreement plus lessor letter authorizing Florida ''Registration Only'' (VIN, make, and year must appear in the letter)', '', 'optional_upload', '{}'),
  ('fl-insurance-proof', 'Proof of current Florida PDL and PIP insurance (insurance ID card with company name + policy number; the VIN of the vehicle must be listed on the policy)', '', 'bring_in', '{}'),
  ('sunbiz-registration', 'Sunbiz ''active'' registration printout for the business (showing registered agents)', 'Required when title will be in a business name.', 'optional_upload', '{}'),
  ('certification-of-trust', 'Certification of Trust or full Trust Agreement', 'Required when title will be held in a trust.', 'optional_upload', '{}'),
  ('all-trustees-present-or-poa', 'All trustees present in person OR power of attorney for absent trustees', '', 'bring_in', '{}'),
  ('adult-co-purchaser-present', 'Adult (18+) co-purchaser present to sign the title application', 'Required when the primary purchaser is a minor.', 'bring_in', '{}'),
