  ('photo-id-all-applicants', 'Valid government-issued photo ID for each person signing', '', 'bring_in', '{}'),
  ('fl-driver-license', 'Current Florida driver license or ID', '', 'bring_in', '{}'),
  ('cdl-medical-cert-uploaded', 'DOT medical examiner''s certificate uploaded to the Florida system (by the examining physician''s office)', 'FL cannot accept the paper card at the counter; the physician''s office must upload it to the state system.', 'bring_in', '{}'),
  ('cdl-general-knowledge-exam', 'Pass the CDL General Knowledge written exam (in English, cannot be taken in audio form)', '', 'bring_in', '{}'),
  ('cdl-skills-exam', 'Pass the CDL skills (driving) exam', 'Not eligible until CLP has been held for 2 weeks.', 'bring_in', '{}'),
  ('cdl-application-fee', 'CDL application fee ($75, plus $7 per endorsement)', '', 'bring_in', '{}'),
  ('cdl-late-fee', 'CDL late fee (required when CDL has been expired less than 1 year)', '', 'bring_in', '{}'),
  ('hazmat-tsa-fee', 'TSA background check fee for hazmat endorsement ($91)', '', 'bring_in', '{}'),
  ('hazmat-written-test', 'Pass the Hazmat written test (valid only 60 days; available in English or Spanish; may be taken in audio form)', 'Hazmat fingerprinting is not available at the Walton Road office (no fingerprint machine). Hazmat testing and fingerprinting are handled ONLY at the Tradition and Fort Pierce offices. (Source: tcslc-sme policy-questions CDL-1, 2026-07.)', 'bring_in', '{}'),
  ('school-employee-letter-or-id', 'School employment ID card OR letter from the school department on letterhead', 'For any school-district employee required to hold a CDL (NOT limited to school-bus endorsement applicants). Required on every original and every renewal and scanned into the record; qualifies the customer for the reduced school-employee CDL fee. (Source: tcslc-sme policy-questions CDL-2, 2026-07.)', 'optional_upload', '{}'),
  ('valid-out-of-state-cdl', 'Valid out-of-state CDL (from a US state or territory)', '', 'bring_in', '{}'),
  ('cdl-endorsement-fee-per', '$7 endorsement fee for each CDL endorsement requested', '', 'bring_in', '{}'),
  ('poa-document', 'Power of attorney authorizing someone other than the owner to sign the title paperwork (a general, durable, or limited POA is accepted — the HSMV 82053 form is NOT required)', 'Any general, durable, or limited POA is accepted as long as it grants authority to conduct the requested motor-vehicle transaction — HSMV 82053 is one option, not a requirement. A POA executed on or after 2011-10-01 must be signed by the principal, include two witnesses, and be notarized OR contain a perjury clause in lieu of notarization. If a durable POA is used to title the vehicle into the appointee''s own name, the ORIGINAL durable POA is required. [Confirmed by TCSLC staff — policy-questions TITLE-6, 2026-07.]', 'form', '{}'),
  ('odometer-disclosure-bill-of-sale', 'Odometer disclosure — completed on HSMV 82050 bill of sale if not present on the title', '', 'form', '{}'),
  ('fl-driver-license-to-renew', 'Current Florida driver license or ID card (the credential you are renewing)', '', 'bring_in', '{}'),
  ('mydmv-portal-referral', 'Renew online at MyDMV Portal (https://mydmvportal.flhsmv.gov/). Credential mailed within 2-3 weeks. $2 online processing fee applies in addition to the renewal fee.', 'Only offered every other renewal cycle per FLHSMV policy. If customer used online last time, they must come in-office.', 'form', '{}'),
  ('dd214-or-veteran-id', 'DD-214 discharge document (any member-copy) or VA-issued veteran ID card to add the ''V'' designation', '', 'optional_upload', '{}'),
  ('va-100-percent-disability-letter', 'VA letter documenting 100% total and permanent service-connected disability rating (required for no-fee credential per §322.21)', '', 'optional_upload', '{}'),
  ('ssa-record-updated', 'Confirmation that your Social Security Administration record already reflects your new name (FLHSMV will cross-check this at the counter; visit SSA before your office appointment if not yet done)', 'Pre-requisite task, not a document — the customer must have visited the Social Security Administration and updated their name before coming to the tax collector. SSA card does not need to be presented (only original one for REAL ID verification).', 'form', '{}'),
  ('tlsae-course-completion', 'Proof of completion of the Traffic Law & Substance Abuse Education (TLSAE) or Driver Education Traffic Safety (DETS) course from an FLHSMV-approved provider', 'Approved providers report completion electronically to FLHSMV; no physical certificate required at counter. Required for any first-time licensee who has never held a DL in any state or country.', 'form', '{}'),
  ('parent-proctoring-form', 'Parent Proctoring Form (HSMV 71144) — notarized OR signed in front of a driver license examiner — for online Class E knowledge exam by applicants under 18', '', 'form', '{}'),
  ('parent-consent-form', 'Parental Consent for Driver Application of a Minor (HSMV 71142) — signed with parent/guardian present, in office', '', 'form', '{}'),
  ('parent-id-valid', 'Parent or legal guardian must bring a valid government-issued photo ID to co-sign for the minor applicant', '', 'bring_in', '{}'),
  ('cdl-general-knowledge-exam-scheduling', 'Schedule the in-office Class E knowledge exam (50 questions, 80% required to pass, English only) at your driver license service center', 'Not a document — an in-office exam appointment. $30 first-attempt fee (standard Class E learner application).', 'form', '{}'),
  ('current-registration-or-renewal-notice', 'Current or most-recent vehicle registration OR renewal notice (copy acceptable)', '', 'optional_upload', '{}'),
  ('hvut-2290-proof', 'IRS Form 2290 showing the Heavy Vehicle Use Tax has been paid (or proof of exemption, e.g., vehicle purchased within 60 days)', 'Required for vehicles with GVW of 55,000 lbs or more. Must match the VIN on registration and insurance; no alterations accepted.', 'optional_upload', '{}'),
