  ('hsmv-82101', 'Application for Duplicate or Lost-in-Transit / Reassignment of a Motor Vehicle, Mobile Home or Vessel Title Certificate (HSMV 82101)', 'Used for duplicate titles. Must be signed by all owners if title is joined by ''and''.', 'form', '{}'),
