  ('builder-receipts', 'Receipts and bill of materials for parts purchased to build the vehicle (used to calculate sales tax basis)', 'Sales tax on a homemade vehicle is calculated from the cost of materials, not a purchase price.', 'optional_upload', '{}'),
  ('btr-online-referral', 'Apply online at https://stlucie.county-taxes.com/btexpress — fees are calculated automatically based on the business classification you select.', '', 'form', '{}'),
  ('tdt-online-referral', 'File online at the St. Lucie Tourist Development Tax portal (stlucie.county-taxes.com/tourist) — quarterly returns and payments are processed electronically.', '', 'form', '{}'),
  ('business-entity-proof', 'Proof of business entity — any one of: FEID number, FL sales-tax registration number, or Sunbiz active-registration printout', '', 'optional_upload', '{}'),
  ('trust-certification', 'Trust certification or trust agreement showing the trustee''s authority to transfer title', '', 'optional_upload', '{}'),
  ('certified-weight-slip', 'Certified weight slip from a public scale (CAT scale at a truck stop, county weigh station, or commercial scale) showing the trailer''s empty net weight', 'Required for any trailer registration. The 2,000-lb cutoff between registration-only and title-required is determined by this slip. CAT scales at most truck stops will provide one for ~$15.', 'bring_in', '{}'),
  ('parts-receipts-trailer', 'Receipts for parts purchased to build the trailer (frame, axles, wheels, lights, hitch, hardware) — used to calculate 6% sales tax basis', 'Florida charges 6% sales tax on the total material cost for homemade trailers. Bring every receipt you have. If receipts are incomplete, the office may estimate from market value at clerk''s discretion.', 'optional_upload', '{}'),
  ('prior-owner-bill-of-sale-trailer', 'Bill of sale signed by the previous owner showing trailer description (make/model/year/VIN if any), purchase price, and date', 'Used to calculate 6% sales tax basis on a private-purchase trailer. For trailers <2,000 lb, this is the primary proof of ownership (no title exists).', 'optional_upload', '{}'),
  ('dealer-bill-of-sale-trailer', 'Dealer bill of sale showing trailer description, purchase price, and dealer-collected sales tax', 'Dealers collect FL sales tax at point of sale and provide a bill of sale showing the breakdown. Tax collector verifies tax was collected; otherwise calculates and collects at the counter.', 'optional_upload', '{}'),
  ('prior-fl-title-signed-by-seller', 'Original Florida trailer title from the prior owner, signed over to the customer (photocopies not accepted)', 'Required for trailers ≥2,000 lb that already have a Florida title. Seller signs the back; customer brings to tax collector.', 'bring_in', '{}'),
  ('death-certificate-inheritance', 'Certified death certificate of the owner named on the title', 'Inheritance/deceased-owner title transfer. Confirmed by St. Lucie tax-office testers (tax423/tax424) as required to establish the owner is deceased. The ADDITIONAL estate documents beyond the death certificate (will, Letters of Administration, FLHSMV decedent affidavit) depend on the survivorship / will / probate path and are confirmed at the counter — see vehicle-title-transfer.review.md for the per-path checklist still to be finalized with the office.', 'optional_upload', '{}')
